// LabWired Pathfinder — hobby rocket flight computer (STM32F411 BlackPill)
// Barometric apogee deployment, launch/burnout detection, camera control,
// arm-switch interlock, single pyro channel with continuity sense.
// The loop sleeps with WFI between samples, as a battery-powered altimeter should.
#include <Arduino.h>
#include <Wire.h>
#include <SPI.h>
#include <math.h>

// ---- Pins ----
static const uint32_t PIN_PYRO     = PB0;   // N-MOSFET gate: e-match low side
static const uint32_t PIN_CONT     = PB1;   // continuity sense, HIGH = e-match present
static const uint32_t PIN_ARM      = PB12;  // arm switch to GND, LOW = armed
static const uint32_t PIN_BUZZ     = PB13;  // buzzer low-side MOSFET gate
static const uint32_t PIN_LED      = PB14;  // external status LED
static const uint32_t PIN_CAM_PWR  = PB15;  // camera 5 V high-side switch (via NPN)
static const uint32_t PIN_CAM_REC  = PB8;   // camera record button (open collector)
static const uint32_t PIN_SD_CS    = PA4;
static const uint32_t PIN_VBAT     = PA0;   // VBAT / 2
static const uint32_t PIN_BOARD_LED = PC13; // active low

static const uint8_t BARO = 0x76, IMU = 0x68;

// ---- Flight clock ----
// The LabWired twin runs ~2 s of MCU time per verify call (115 s wall); a full flight is ~92 s.
// TWIN_TIME_SCALE runs the flight clock (sampling, lockouts, timers) 60x faster in the
// twin. I2C/SPI transactions stay real-time. SET TO 1 BEFORE FLASHING REAL HARDWARE.
#define TWIN_TIME_SCALE 60
static uint32_t flightMs() { return (uint32_t)(((uint64_t)micros() * TWIN_TIME_SCALE) / 1000ULL); }
static void flightDelay(uint32_t ms) { delayMicroseconds((ms * 1000UL) / TWIN_TIME_SCALE); }

// ---- Flight constants ----
static const float LAUNCH_G          = 2.5f;   // sensed axial g for launch
static const uint32_t LAUNCH_HOLD_MS = 60;
static const float LAUNCH_ALT_M      = 15.0f;  // baro backup launch detect
static const uint32_t APOGEE_LOCKOUT_MS = 3000; // no deploy before T+3 s
static const float APOGEE_DROP_M     = 1.5f;   // below max altitude
static const uint8_t APOGEE_CONFIRM  = 2;      // consecutive samples
static const uint32_t PYRO_ON_MS     = 1000;
static const float LAND_BAND_M       = 1.0f;
static const uint32_t LAND_STILL_MS  = 5000;

enum Phase : uint8_t { BOOT, PAD_SAFE, PAD_ARMED, BOOST, COAST, DESCENT, LANDED, FAULT };
static const char *PHASE_NAME[] = {"BOOT","PAD_SAFE","PAD_ARMED","BOOST","COAST","DESCENT","LANDED","FAULT"};
static Phase phase = BOOT;

// ---- BME280 calibration ----
static uint16_t T1; static int16_t T2, T3;
static uint16_t P1; static int16_t P2, P3, P4, P5, P6, P7, P8, P9;
static int32_t tFine;

static float groundPa = 0, altM = 0, maxAltM = 0, axialG = 1.0f, maxG = 0;
static uint32_t launchMs = 0, burnoutMs = 0, apogeeMs = 0, deployMs = 0, landMs = 0;
static uint32_t phaseMs = 0, highGSince = 0, stillSince = 0, pyroOffAt = 0, camRecReleaseAt = 0;
static float stillRef = 0;
static uint8_t dropCount = 0;
static bool pyroFired = false, sdOk = false, camOn = false, camRecStarted = false;
static uint32_t samples = 0;

// ---------------------------------------------------------------- I2C
static bool rd(uint8_t a, uint8_t r, uint8_t *b, uint8_t n) {
  Wire.beginTransmission(a); Wire.write(r);
  if (Wire.endTransmission(false) != 0) return false;
  if (Wire.requestFrom(a, n) != n) return false;
  for (uint8_t i = 0; i < n; ++i) b[i] = Wire.read();
  return true;
}
static void wr(uint8_t a, uint8_t r, uint8_t v) {
  Wire.beginTransmission(a); Wire.write(r); Wire.write(v); Wire.endTransmission();
}
static void compT(int32_t adc) {
  int32_t v1 = ((((adc >> 3) - ((int32_t)T1 << 1))) * ((int32_t)T2)) >> 11;
  int32_t v2 = (((((adc >> 4) - ((int32_t)T1)) * ((adc >> 4) - ((int32_t)T1))) >> 12) * ((int32_t)T3)) >> 14;
  tFine = v1 + v2;
}
static float compP(int32_t adc) {
  int64_t v1 = ((int64_t)tFine) - 128000, v2 = v1 * v1 * (int64_t)P6;
  v2 += (v1 * (int64_t)P5) << 17; v2 += ((int64_t)P4) << 35;
  v1 = ((v1 * v1 * (int64_t)P3) >> 8) + ((v1 * (int64_t)P2) << 12);
  v1 = (((((int64_t)1) << 47) + v1)) * ((int64_t)P1) >> 33;
  if (v1 == 0) return 0;
  int64_t p = 1048576 - adc; p = (((p << 31) - v2) * 3125) / v1;
  v1 = (((int64_t)P9) * (p >> 13) * (p >> 13)) >> 25; v2 = (((int64_t)P8) * p) >> 19;
  p = ((p + v1 + v2) >> 8) + (((int64_t)P7) << 4);
  return (float)p / 256.0f;
}
static bool initBaro() {
  uint8_t id = 0;
  if (!rd(BARO, 0xD0, &id, 1) || id != 0x60) return false;
  uint8_t c[24];
  if (!rd(BARO, 0x88, c, 24)) return false;
  T1 = c[0] | c[1] << 8; T2 = c[2] | c[3] << 8; T3 = c[4] | c[5] << 8;
  P1 = c[6] | c[7] << 8; P2 = c[8] | c[9] << 8; P3 = c[10] | c[11] << 8; P4 = c[12] | c[13] << 8;
  P5 = c[14] | c[15] << 8; P6 = c[16] | c[17] << 8; P7 = c[18] | c[19] << 8; P8 = c[20] | c[21] << 8; P9 = c[22] | c[23] << 8;
  wr(BARO, 0xF2, 0x01); wr(BARO, 0xF5, 0x00); wr(BARO, 0xF4, 0x27);
  return true;
}
static bool initImu() {
  uint8_t who = 0;
  if (!rd(IMU, 0x75, &who, 1) || who != 0x68) return false;
  wr(IMU, 0x6B, 0x00);       // wake
  wr(IMU, 0x1C, 0x18);       // +-16 g
  wr(IMU, 0x1A, 0x03);       // DLPF 44 Hz
  return true;
}
static bool readBaro(float &pa) {
  uint8_t b[6];
  if (!rd(BARO, 0xF7, b, 6)) return false;
  int32_t ap = (int32_t)b[0] << 12 | b[1] << 4 | b[2] >> 4, at = (int32_t)b[3] << 12 | b[4] << 4 | b[5] >> 4;
  compT(at); pa = compP(ap);
  return pa > 30000.0f && pa < 110000.0f;
}
// Rocket axis = IMU +Y (PCB long axis points to the nose).
static bool readAxialG(float &g) {
  uint8_t b[2];
  if (!rd(IMU, 0x3D, b, 2)) return false;
  g = (int16_t)(b[0] << 8 | b[1]) / 2048.0f;
  return true;
}
static float altitude(float pa) { return 44330.0f * (1.0f - powf(pa / groundPa, 0.190295f)); }

// ---------------------------------------------------------------- SD (raw sector log)
static uint8_t sdCmd(uint8_t cmd, uint32_t arg, uint8_t crc) {
  SPI.transfer(0xFF);
  SPI.transfer(0x40 | cmd);
  SPI.transfer(arg >> 24); SPI.transfer(arg >> 16); SPI.transfer(arg >> 8); SPI.transfer(arg);
  SPI.transfer(crc);
  for (uint8_t i = 0; i < 10; ++i) { uint8_t r = SPI.transfer(0xFF); if (!(r & 0x80)) return r; }
  return 0xFF;
}
static bool initSd() {
  SPI.beginTransaction(SPISettings(400000, MSBFIRST, SPI_MODE0));
  digitalWrite(PIN_SD_CS, HIGH);
  for (uint8_t i = 0; i < 10; ++i) SPI.transfer(0xFF);
  digitalWrite(PIN_SD_CS, LOW);
  bool ok = sdCmd(0, 0, 0x95) == 0x01;
  if (ok) { sdCmd(8, 0x1AA, 0x87); for (uint8_t i = 0; i < 4; ++i) SPI.transfer(0xFF); }
  uint8_t r = 0xFF;
  for (uint16_t i = 0; ok && i < 100; ++i) { sdCmd(55, 0, 0x65); r = sdCmd(41, 0x40000000, 0x77); if (r == 0) break; }
  digitalWrite(PIN_SD_CS, HIGH); SPI.transfer(0xFF);
  SPI.endTransaction();
  return ok && r == 0;
}
static bool sdWriteSector(uint32_t lba, const char *text) {
  SPI.beginTransaction(SPISettings(4000000, MSBFIRST, SPI_MODE0));
  digitalWrite(PIN_SD_CS, LOW);
  bool ok = sdCmd(24, lba, 0xFF) == 0;
  if (ok) {
    SPI.transfer(0xFE);
    size_t n = strlen(text);
    for (uint16_t i = 0; i < 512; ++i) SPI.transfer(i < n ? (uint8_t)text[i] : 0);
    SPI.transfer(0xFF); SPI.transfer(0xFF);
    uint8_t resp = SPI.transfer(0xFF);
    ok = (resp & 0x1F) == 0x05;
    for (uint16_t i = 0; i < 2000 && SPI.transfer(0xFF) == 0; ++i) {}
  }
  digitalWrite(PIN_SD_CS, HIGH); SPI.transfer(0xFF);
  SPI.endTransaction();
  return ok;
}

// ---------------------------------------------------------------- outputs
static void event(const char *name) {
  Serial.print(name); Serial.print(" t_ms="); Serial.print(launchMs ? flightMs() - launchMs : 0);
  Serial.print(" alt_m="); Serial.print(altM, 1); Serial.print(" g="); Serial.println(axialG, 2);
}
static void setPhase(uint8_t p) {   // uint8_t: the .ino prototype pass runs before the enum
  phase = (Phase)p; phaseMs = flightMs();
  Serial.print("PHASE "); Serial.println(PHASE_NAME[p]);
}
static void beep(uint32_t ms) { digitalWrite(PIN_BUZZ, HIGH); flightDelay(ms); digitalWrite(PIN_BUZZ, LOW); }
static void cameraPower(bool on) {
  digitalWrite(PIN_CAM_PWR, on ? HIGH : LOW); camOn = on;
  Serial.println(on ? "CAMERA_POWER_ON" : "CAMERA_POWER_OFF");
}
static void cameraRecPulse(const char *label) {
  digitalWrite(PIN_CAM_REC, HIGH); camRecReleaseAt = flightMs() + 600;  // hold "button" 600 ms
  Serial.println(label);
}
static void pyroSafe() { digitalWrite(PIN_PYRO, LOW); pyroOffAt = 0; }
static void fault(const char *why) {
  pyroSafe(); setPhase(FAULT); Serial.print("FAULT "); Serial.println(why);
}

// ---------------------------------------------------------------- flight logic
static uint32_t samplePeriod() {
  switch (phase) {
    case BOOST: case COAST: return 20;     // 50 Hz
    case PAD_ARMED: case PAD_SAFE: return 100;   // 10 Hz
    case DESCENT: return 500;              // 2 Hz: enough for landing detection
    default: return 500;
  }
}

static void calibrateGround() {
  float sum = 0; uint8_t n = 0;
  for (uint8_t i = 0; i < 16; ++i) { float pa; if (readBaro(pa)) { sum += pa; ++n; } flightDelay(5); }
  groundPa = n ? sum / n : 101325.0f;
  Serial.print("GROUND_PA="); Serial.println(groundPa, 0);
}

static void flightStep(uint32_t now) {
  float pa;
  if (!readBaro(pa)) { if (phase >= BOOST && phase <= DESCENT) { Serial.println("BARO_READ_FAIL"); return; } fault("BARO"); return; }
  bool needImu = phase <= COAST;
  if (needImu && !readAxialG(axialG)) { fault("IMU"); return; }
  ++samples;
  altM = altitude(pa);
  if (axialG > maxG) maxG = axialG;

  switch (phase) {
    case PAD_SAFE:
      if (digitalRead(PIN_ARM) == LOW) {
        calibrateGround(); altM = 0;
        Serial.print("PYRO_CONTINUITY="); Serial.println(digitalRead(PIN_CONT) == HIGH ? 1 : 0);
        cameraPower(true);
        setPhase(PAD_ARMED);
        beep(150);
      }
      break;
    case PAD_ARMED:
      if (digitalRead(PIN_ARM) == HIGH) { cameraPower(false); setPhase(PAD_SAFE); break; }
      if (camOn && !camRecStarted && now - phaseMs > 1000) { camRecStarted = true; cameraRecPulse("CAMERA_REC_START"); }
      if (axialG > LAUNCH_G) { if (!highGSince) highGSince = now; } else highGSince = 0;
      if ((highGSince && now - highGSince >= LAUNCH_HOLD_MS) || altM > LAUNCH_ALT_M) {
        launchMs = highGSince ? highGSince : now; maxAltM = altM;
        event("LAUNCH"); setPhase(BOOST);
      }
      break;
    case BOOST:
      if (axialG < 0.0f && now - launchMs > 300) { burnoutMs = now; event("BURNOUT"); setPhase(COAST); }
      // fall through to apogee tracking
    case COAST:
      if (altM > maxAltM) { maxAltM = altM; apogeeMs = now; dropCount = 0; }
      else if (maxAltM - altM >= APOGEE_DROP_M) ++dropCount;
      if (now - launchMs >= APOGEE_LOCKOUT_MS && dropCount >= APOGEE_CONFIRM && !pyroFired) {
        event("APOGEE_DETECTED");
        if (digitalRead(PIN_ARM) == LOW) {
          digitalWrite(PIN_PYRO, HIGH); pyroFired = true; deployMs = now; pyroOffAt = now + PYRO_ON_MS;
          event("DEPLOY");
        } else {
          Serial.println("DEPLOY_INHIBITED_DISARMED");
        }
        setPhase(DESCENT); stillRef = altM; stillSince = now;
      }
      break;
    case DESCENT:
      if (fabsf(altM - stillRef) > LAND_BAND_M) { stillRef = altM; stillSince = now; }
      else if (now - stillSince >= LAND_STILL_MS && altM < 10.0f) {
        landMs = stillSince; event("LANDED"); setPhase(LANDED);
        cameraRecPulse("CAMERA_REC_STOP");
      }
      break;
    default: break;
  }
}

static void report() {
  char line[200];
  snprintf(line, sizeof(line),
    "FLIGHT apogee_m=%d apogee_t_ms=%lu burnout_t_ms=%lu deploy_t_ms=%lu land_t_ms=%lu max_g=%d.%d samples=%lu",
    (int)lroundf(maxAltM), (unsigned long)(apogeeMs - launchMs), (unsigned long)(burnoutMs - launchMs),
    (unsigned long)(deployMs - launchMs), (unsigned long)(landMs - launchMs),
    (int)maxG, (int)(fabsf(maxG - (int)maxG) * 10), (unsigned long)samples);
  Serial.println(line);
  if (sdOk) Serial.println(sdWriteSector(2048, line) ? "SD_LOG_WRITTEN lba=2048" : "SD_LOG_WRITE_FAIL");
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_PYRO, OUTPUT); digitalWrite(PIN_PYRO, LOW);   // pyro safe first
  pinMode(PIN_BUZZ, OUTPUT); pinMode(PIN_LED, OUTPUT); pinMode(PIN_BOARD_LED, OUTPUT);
  pinMode(PIN_CAM_PWR, OUTPUT); pinMode(PIN_CAM_REC, OUTPUT); pinMode(PIN_SD_CS, OUTPUT);
  digitalWrite(PIN_CAM_PWR, LOW); digitalWrite(PIN_CAM_REC, LOW); digitalWrite(PIN_SD_CS, HIGH);
  pinMode(PIN_ARM, INPUT_PULLUP); pinMode(PIN_CONT, INPUT); pinMode(PIN_VBAT, INPUT_ANALOG);
  analogReadResolution(12);
  Wire.setSCL(PB6); Wire.setSDA(PB7); Wire.begin(); Wire.setClock(400000);
  SPI.setSCLK(PA5); SPI.setMISO(PA6); SPI.setMOSI(PA7); SPI.begin();
  Serial.println("PATHFINDER_FC_BOOT");
  Serial.print("FLIGHT_CLOCK_SCALE="); Serial.println(TWIN_TIME_SCALE);
  if (TWIN_TIME_SCALE != 1) Serial.println("WARNING TWIN BUILD - SET TWIN_TIME_SCALE 1 BEFORE FLIGHT");
  bool b = initBaro(), i = initImu();
  Serial.print("SELFTEST baro="); Serial.print(b); Serial.print(" imu="); Serial.println(i);
  sdOk = initSd();
  Serial.println(sdOk ? "SD_OK" : "SD_FAIL");
  if (!b || !i) { fault("SELFTEST"); return; }
  groundPa = 101325.0f;
  setPhase(PAD_SAFE);
}

void loop() {
  static uint32_t nextSample = 0, ledAt = 0;
  static bool reported = false;
  uint32_t now = flightMs();
  if (pyroOffAt && (int32_t)(now - pyroOffAt) >= 0) { pyroSafe(); event("PYRO_OFF"); }
  if (camRecReleaseAt && (int32_t)(now - camRecReleaseAt) >= 0) {
    digitalWrite(PIN_CAM_REC, LOW); camRecReleaseAt = 0;
    if (phase == LANDED && camOn) cameraPower(false);
  }
  if (phase != FAULT && (int32_t)(now - nextSample) >= 0) {
    nextSample = now + samplePeriod();
    flightStep(now);
  }
  if (phase == LANDED && !reported && !camRecReleaseAt) {
    reported = true; report();
    Serial.println("OUTPUTS_SAFE PYRO=0 CAM=0");
  }
  if ((int32_t)(now - ledAt) >= 0) {   // status LED: slow on pad, fast in flight
    ledAt = now + (phase >= BOOST && phase <= DESCENT ? 100 : 500);
    digitalWrite(PIN_LED, !digitalRead(PIN_LED));
  }
  __WFI();
}
